import 'package:flutter/material.dart';
import '../../services/api/api_client.dart';
import '../../services/api/api_endpoints.dart';
import '../theme/app_colors.dart';
import '../widgets/citizen_shell.dart';
class NotificationsScreen extends StatefulWidget{const NotificationsScreen({super.key});@override State<NotificationsScreen> createState()=>_NotificationsScreenState();}
class _NotificationsScreenState extends State<NotificationsScreen>{List<dynamic> items=[];bool loading=true;@override void initState(){super.initState();_load();}Future<void>_load()async{try{final r=await ApiClient().get(ApiEndpoints.notifications);final d=ApiClient().unwrap(r.data);items=d is List?d:(d is Map&&d['items'] is List?d['items']:const []);}catch(_){ }if(mounted)setState(()=>loading=false);}@override Widget build(BuildContext context)=>CitizenShell(index:3,title:'Alerts',onRefresh:_load,child:loading?const Center(child:CircularProgressIndicator()):items.isEmpty?const Center(child:Text('No new alerts',style:TextStyle(color:AppColors.textSecondary))):ListView.separated(padding:const EdgeInsets.all(16),itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(context,i){final n=Map<String,dynamic>.from(items[i] as Map);return Container(padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(13),border:Border.all(color:AppColors.cardBorder)),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[const CircleAvatar(radius:18,backgroundColor:Color(0xFFEAF0FF),child:Icon(Icons.notifications_none_rounded,size:18,color:Color(0xFF1769FF))),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${n['title']??'Notification'}',style:const TextStyle(fontSize:11,fontWeight:FontWeight.w800)),const SizedBox(height:4),Text('${n['message']??''}',style:const TextStyle(fontSize:9,color:AppColors.textSecondary,height:1.35))]))]));}));}
